import RNA

with open('/tmp/tgt_clean.txt') as f:
    t = f.read().strip()
n = len(t)

# pair map
stack = []
pair = {}
for i, c in enumerate(t):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pair[i] = j
        pair[j] = i

# Solved units from inverse_fold_search (place at their positions)
units = {
    (129, 153): "GGCGCAGGGAAACCGUCGGACAGCC",  # unit 6
    (227, 246): "CGAGUCGCCAAGGGGCAUCG",       # unit 11
}

seq = ['A'] * n

# 1) Place solved units
for (a, b), u in units.items():
    for k, ch in enumerate(u):
        seq[a + k] = ch

# 2) For positions NOT covered by units, use structure-driven fill:
#    pairs -> G-C (GC clamp), unpaired -> A; tetraloop caps GAAA
covered = set()
for (a, b), u in units.items():
    for k in range(a, b + 1):
        covered.add(k)

# 3) Fill non-unit regions: GC pairs, tetraloop caps
# Find hairpin loops entirely outside units
caps4 = ["GAAA", "UUCG", "GCAA", "CUUG"]
hairpins = []
for i in range(n):
    if t[i] == '(' and pair.get(i, i) > i:
        j = pair[i]
        k = i + 1
        L = 0
        while k < j and t[k] == '.':
            L += 1
            k += 1
        if k == j and L > 0:
            hairpins.append((i, j, L))

# fill non-unit positions with GC pairs first
for i in range(n):
    if i in covered:
        continue
    if i in pair and i < pair[i]:
        j = pair[i]
        seq[i] = 'G'
        seq[j] = 'C'

# apply tetraloop caps to hairpins NOT inside units
hp_idx = 0
for (i, j, L) in hairpins:
    # skip if this hairpin is inside a unit region
    if any(a <= i < b for (a, b) in units):
        continue
    if L == 4:
        cap = caps4[hp_idx % 4]
        hp_idx += 1
    elif L == 6:
        cap = "AAAAAA"
    else:
        cap = "A" * L
    for o, ch in enumerate(cap):
        if i + 1 + o not in covered:
            seq[i + 1 + o] = ch

s = ''.join(seq)
print("LEN", len(s))
print(s)
open('/tmp/cand2.txt', 'w').write(s)

fc = RNA.fold_compound(s)
ss, mfe = fc.mfe()
print("MFE match", ss == t, "mfe", mfe, "bpdist", RNA.bp_distance(t, ss))

